    'finalizeGate on + ledger in the final answer emits TaskLedgerEvent',
    () async {
      final events = await runTurns([
        toolTurn([ToolCall(id: 't1', name: 'bash', arguments: const {})]),
        textTurn(ledgerText),
      ], finalizeGate: true);
      final ledgerEvents = events.whereType<TaskLedgerEvent>().toList();
