Future<_OverWindowGuardStep> _overWindowGuardTurn(
  Context context,
  Context requestContext,
  AgentLoopConfig config,
  AgentEventSink emit,
  bool reliefUsed,
  CancelToken? cancelToken,
  int window,
  int tokens,
) async {
