      for (final variant in variants) {
        expect(
          () => fixtureFor(eventFixturesDir, 'message_update_$variant'),
          returnsNormally,
          reason: 'missing golden for message_update_$variant',
        );
      }
      expect(
        eventFixtures.where((f) => f.kind == 'message_update'),
        hasLength(variants.length),
