```task-ledger
- requirement: key material \$key is gone
  command: echo "\$key"
  expected: empty output
  actual: sk-live-topsecret-credential-42
  status: pass
```
''';

  Future<List<CustomRecord>> runAndRecords({
    RedactionPipeline? pipeline,
  }) async {
    final env = MemoryExecutionEnv(cwd: '/work');
