) async {
  // One entry per started tool call, in assistant source order.
  final pending = <Future<_FinalizedToolCall>>[];

  for (final toolCall in toolCalls) {
    await emit(
      ToolExecutionStartEvent(
        toolCallId: toolCall.id,
        toolName: toolCall.name,
